// === Tab: Objs ===
class Rect {
	constructor (x,y,w,h,angle) {
		Object.assign(this, {x,y,w,h,angle})
	}
	intersectRect(r2) {
		return rectanglesIntersect(this,r2)
	}
	intersectCircle(c2) {
		return c2.intersectRect(this)
	}
	containsPoint(p) {
		return isPointInRotatedRect(this,p);
	}
	distPoint (p) {
		return pointToRotatedRectDist(this, p);
	}
	vertices() {
		return getRotatedVertices(this);
	}
	mbr() {
		let m = new MBR();
		for (let v of this.vertices()) m.add(v);
		return m;
	}
}

class Circle {
	constructor (c,r) {
		// center and radius
		Object.assign(this, {c,r});
	}
	intersectRect(r2) {
		return r2.distPoint(this.c) < this.r;
	}
	intersectCircle(c2) {
		return c2.c.dist(this.c) < this.r+c2.r;
	}
	distPoint (p) {
		return max(0,p.dist(this.c) - this.r);
	}
	containsPoint(p) {
		return this.c.dist(p) < this.r;
	}
	mbr() {
		return MBR.fromRect(this.c.x-this.r,this.c.y-this.r,this.r*2,this.r*2);
	}
}

function rectanglesIntersect(rect1, rect2) {
  const vertices1 = getRotatedVertices(rect1);
  const vertices2 = getRotatedVertices(rect2);

  // Check all axes of both rectangles
  const axes = getAxes(vertices1).concat(getAxes(vertices2));
  for (let axis of axes) {
    const projection1 = projectOntoAxis(vertices1, axis);
    const projection2 = projectOntoAxis(vertices2, axis);

    // If projections do not overlap, rectangles do not intersect
    if (projection1[1] < projection2[0] || projection2[1] < projection1[0]) {
      return false;
    }
  }

  // All projections overlap, so rectangles intersect
  return true;
}

function getRotatedVertices(rect) {
  const cx = rect.x;
  const cy = rect.y;
  var w = rect.w / 2; // Half width
  var h = rect.h / 2; // Half height
  const angle = rect.angle;

  // Define the four corners relative to the center
  const corners = [
    createVector(-w, -h),
    createVector(w, -h),
    createVector(w, h),
    createVector(-w, h),
  ];

  // Rotate and translate corners
  return corners.map(corner => {
    const x = corner.x * cos(angle) - corner.y * sin(angle);
    const y = corner.x * sin(angle) + corner.y * cos(angle);
    return createVector(cx + x, cy + y);
  });
}

function getAxes(vertices) {
  var axes = [];
  for (let i = 0; i < vertices.length; i++) {
    const p1 = vertices[i];
    const p2 = vertices[(i + 1) % vertices.length];
    const edge = p2.copy().sub(p1);
    const normal = createVector(-edge.y, edge.x); // Perpendicular vector
    axes.push(normal.normalize());
  }
  return axes;
}

function projectOntoAxis(vertices, axis) {
  let min = axis.dot(vertices[0]);
  let max = min;
  for (let i = 1; i < vertices.length; i++) {
    const projection = axis.dot(vertices[i]);
    min = Math.min(min, projection);
    max = Math.max(max, projection);
  }
  return [min, max];
}

function isPointInRotatedRect({x, y, w, h, angle}, p) {

  // Translate the point and rectangle center to origin
  let dx = p.x - x;
  let dy = p.y - y;

  // Reverse the rotation of the point
  let cosAng = cos(-angle);
  let sinAng = sin(-angle);
  let rotatedX = dx * cosAng - dy * sinAng;
  let rotatedY = dx * sinAng + dy * cosAng;

  // Check if the rotated point is within the axis-aligned rectangle
  return (
    rotatedX >= -w / 2 &&
    rotatedX <= w / 2 &&
    rotatedY >= -h / 2 &&
    rotatedY <= h / 2
  );
}

function pointToRotatedRectDist({x,y,w,h,angle}, p) {
  // Calculate the center of the rectangle
  var cx = x ;
  var cy = y ;

  // Translate the point and rectangle center to origin
  var dx = p.x - cx;
  var dy = p.y - cy;

  // Reverse the rotation of the point
  var cosAng = cos(-angle);
  var sinAng = sin(-angle);
  var rotatedX = dx * cosAng - dy * sinAng;
  var rotatedY = dx * sinAng + dy * cosAng;

  // Calculate the distance from the point to the axis-aligned rectangle
  let ax = -w / 2;
  let ay = -h / 2;
  let bx = w / 2;
  let by = h / 2;

  // Clamp the point within the rectangle bounds
  let closestX = constrain(rotatedX, ax, bx);
  let closestY = constrain(rotatedY, ay, by);

  // Compute the Euclidean distance between the point and the closest point
  let distX = rotatedX - closestX;
  let distY = rotatedY - closestY;

  return sqrt(distX * distX + distY * distY);
}


