/**
 * Axis aligned bounding box
 **/
class MBR {
  // Minimum Bounding Rectangle

  constructor(...args) {
    // MBR for a variable number of points
    this.min = createVector(Infinity, Infinity);
    this.max = createVector(-Infinity,-Infinity);
    for (let p of args) this.add(p);
  }

	static fromRect(x, y, w, h) {
		// Builds from a rectangle
		let mbr = new MBR();
		mbr.min = createVector(x,y);
		mbr.max = createVector(x+w, y+h);
		return mbr;
	}

  valid() {
    // Whether this is a valid MBR
    return this.min.x <= this.max.x && this.min.y <= this.max.y;
  }

  size() {
    // Size of this box
    return createVector(this.max.x - this.min.x, this.max.y - this.min.y);
  }

  center() {
    // Center of the box
    return this.min.copy().add(this.max).mult(0.5);
  }

  add(p) {
    // Adds a new point to this MBR
    this.min.x = Math.min(p.x, this.min.x);
    this.min.y = Math.min(p.y, this.min.y);
    this.max.x = Math.max(p.x, this.max.x);
    this.max.y = Math.max(p.y, this.max.y);
  }

	containedIn (other) {
		// Whether this mbr contained in other mbr
		return other.min.x <= this.min.x && other.max.x >= this.max.x &&
			other.min.y <= this.min.y && other.max.y >= this.max.y 
	}

  contains(p, r = 0) {
    // Whether MBR contains a point / circle
    return (
      p.x + r >= this.min.x &&
      p.y + r >= this.min.y &&
      p.x - r < this.max.x &&
      p.y - r < this.max.y
    );
  }

  pointDist(p) {
    // Distance from box to point
    var dx = Math.max(this.min.x - p.x, 0, p.x - this.max.x);
    var dy = Math.max(this.min.y - p.y, 0, p.y - this.max.y);
    return Math.sqrt(dx * dx + dy * dy);
  }

  intersects(other) {
    // Whether this MBR intersects another MBR
    let minx = Math.max(other.min.x, this.min.x);
    let maxx = Math.min(other.max.x, this.max.x);
    if (minx >= maxx) return false;
    let miny = Math.max(other.min.y, this.min.y);
    let maxy = Math.min(other.max.y, this.max.y);
    return miny < maxy;
  }

  intersection(other) {
    // Returns intersection with another MBR
    let ret = new MBR();
    ret.min.x = Math.max(other.min.x, this.min.x);
    ret.max.x = Math.min(other.max.x, this.max.x);
    ret.min.y = Math.max(other.min.y, this.min.y);
    ret.max.y = Math.min(other.max.y, this.max.y);
    return ret;
  }

  union(other) {
    // Returns union with another MBR
    var ret = new MBR();
    ret.min.x = Math.min(other.min.x, this.min.x);
    ret.max.x = Math.max(other.max.x, this.max.x);
    ret.min.y = Math.min(other.min.y, this.min.y);
    ret.max.y = Math.max(other.max.y, this.max.y);
    return ret;
  }

}

// === Tab: SearchDS ===
/**
 * A simple 2d search data structure based on a regular grid
 **/
class SearchDS {

	constructor (x, y, w, h, nx = 30, ny = 30) {
		Object.assign(this, {x,y,w,h,nx,ny});
		this.mbr = MBR.fromRect(x,y,w,h);
		this.dx = w/nx;
		this.dy = h/ny;
		this.cells = [];
	}

	*cellIndicesForMbr (mbr) {
		let ixmin = floor((mbr.min.x-this.x)/this.dx);
		let ixmax = floor((mbr.max.x-this.x)/this.dx);
		let iymin = floor((mbr.min.y-this.y)/this.dy);
		let iymax = floor((mbr.max.y-this.y)/this.dy);
		for (let ix = ixmin; ix <= ixmax; ix++) {
			for (let iy = iymin; iy <= iymax; iy++) {
				yield ix + iy * this.nx;
			}
		}
	}

	add (mbr, value) {
		if (!mbr.containedIn(this.mbr)) throw "MBR not contained in search ds";
		for (let icell of this.cellIndicesForMbr(mbr)) {
			let cell = this.cells[icell] || [];
			cell.push ({mbr,value});
			this.cells[icell] = cell
		}
	}

	*valuesInMbr (mbr) {
		if (!mbr.containedIn(this.mbr)) throw "MBR not contained in search ds";
		let duplicates = new Set();
		for (let icell of this.cellIndicesForMbr(mbr)) {
			var cell = this.cells[icell] || [];
			for (let entry of cell) {
				if (entry.mbr.intersects(mbr) && !duplicates.has(entry.value)) {
					yield (entry.value);
					duplicates.add(entry.value)
				}
			}
		}
	}
}

